SELECT

FROM user_practice_progress p
WHERE p.user_id = #{userId}
  AND p.subject_id = #{subjectId}
  AND p.practice_type = #{practiceType}
  AND p.outline_id = #{outlineId}
LIMIT 1

SELECT

FROM user_practice_progress p
WHERE p.user_id = #{userId}
  AND p.subject_id = #{subjectId}
ORDER BY p.updated_at DESC, p.id DESC
LIMIT 200
